package main

import (
	"fmt"
	"sync"
	"time"
)

type entry struct {
	value    string
	expireAt time.Time
}

// LocalCache 是进程内的第一级缓存
type LocalCache struct {
	mu   sync.Mutex
	data map[string]entry
	ttl  time.Duration
}

func (c *LocalCache) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.data[key]
	if !ok || time.Now().After(e.expireAt) {
		// 本地没有或已过期，回源到分布式缓存
		return "", false
	}
	return e.value, true
}

func (c *LocalCache) Set(key, value string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[key] = entry{value: value, expireAt: time.Now().Add(c.ttl)}
}

func main() {
	c := &LocalCache{data: map[string]entry{}, ttl: time.Minute}
	c.Set("k", "v")
	v, ok := c.Get("k")
	fmt.Println(v, ok)
	_, ok = c.Get("missing")
	fmt.Println(ok)
}

package main

import (
	"fmt"
	"sync"
)

var (
	mu    sync.RWMutex
	cache = map[string]string{}
)

// 模拟互斥重建：同一时刻只允许一个请求回源
func get(key string) string {
	mu.RLock()
	v, ok := cache[key]
	mu.RUnlock()
	if ok {
		return v
	}
	mu.Lock()
	defer mu.Unlock()
	if v, ok := cache[key]; ok {
		// 双重检查：等锁期间可能已经被别的请求重建好了
		return v
	}
	v = "rebuild-" + key
	cache[key] = v
	return v
}

func main() {
	fmt.Println(get("a"), get("a"))
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	// 队列容量就是削峰的缓冲区
	queue := make(chan int, 100)
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			// 消费者按自己的速度消费
			for n := range queue {
				fmt.Println("消费", n)
			}
		}()
	}
	// 生产者瞬间涌入，请求先入队就返回
	for i := 0; i < 10; i++ {
		queue <- i
	}
	close(queue)
	wg.Wait()
}

