import "fmt"

func main() {
	ids := []int{1, 2, 3, 4, 5}
	const batchSize = 2
	for i := 0; i < len(ids); i += batchSize {
		end := i + batchSize
		if end > len(ids) {
			end = len(ids)
		}
		// 一批一次提交，摊薄网络往返和事务开销
		fmt.Println("批量写入:", ids[i:end])
	}
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	// 用带缓冲的 channel 模拟连接池：同时最多 2 个「连接」在用
	const maxConn = 2
	sem := make(chan struct{}, maxConn)
	var wg sync.WaitGroup
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// 获取连接，没有空闲的就排队等
			sem <- struct{}{}
			// 用完归还连接
			defer func() { <-sem }()
			fmt.Println("处理请求", id)
		}(i)
	}
	wg.Wait()
}

