import "fmt"

// 取模分片：同一个 userID 永远落到同一个分片
func shardOf(userID, shardCount int64) int64 {
	return userID % shardCount
}

func main() {
	for _, id := range []int64{1001, 1002, 1003} {
		fmt.Println(id, "->", shardOf(id, 4))
	}
}

package main

import (
	"fmt"
	"sync"
)

type OrderService struct {
	mu   sync.Mutex
	done map[string]string // 幂等键 -> 已处理的结果
}

func (s *OrderService) Create(key string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	if r, ok := s.done[key]; ok {
		// 重复请求：直接返回上次的结果
		return r
	}
	r := "order-" + key
	s.done[key] = r
	return r
}

func main() {
	s := &OrderService{done: map[string]string{}}
	fmt.Println(s.Create("k1"))
	fmt.Println(s.Create("k1"))
}

package main

import (
	"fmt"
	"sync"
)

var (
	once  sync.Once
	cache []string
)

// 预热：进程启动时先把热点数据加载好
func warmUp() {
	cache = make([]string, 1000)
	for i := range cache {
		cache[i] = fmt.Sprintf("item-%d", i)
	}
}

func main() {
	// 就绪探针通过之后才开始接流量
	once.Do(warmUp)
	fmt.Println(len(cache))
}
